// Current O(n²) approach
for (let i = 0; i < items.length; i++) {
  for (let j = 0; j < filters.length; j++) {
    if (items[i].category === filters[j]) {
      results.push(items[i]);
    }
  }
}

// Optimized O(n) approach
const filterSet = new Set(filters);
const results = items.filter(item => filterSet.has(item.category));

// Current N+1 approach
const users = await User.findAll();
for (const user of users) {
  user.reports = await Report.findAll({ where: { userId: user.id } });
}

// Optimized single query approach
const users = await User.findAll({
  include: [{ model: Report, as: 'reports' }]
});

// Current monolithic function
async function createUser(userData) {
  // Validation
  if (!userData.email || !userData.name) {
    throw new Error('Invalid data');
  }

  // Persistence
  const user = await User.create(userData);

  // Notification
  await emailService.sendWelcome(user.email);

  return user;
}

// Refactored single-responsibility functions
function validateUserData(userData) {
  if (!userData.email || !userData.name) {
    throw new Error('Invalid data');
  }
  return userData;
}

async function persistUser(userData) {
  return await User.create(userData);
}

async function sendWelcomeNotification(user) {
  await emailService.sendWelcome(user.email);
}

async function createUser(userData) {
  const validData = validateUserData(userData);
  const user = await persistUser(validData);
  await sendWelcomeNotification(user);
  return user;
}

